var url=baseUrl.replace(/.html/,"_1.html")
var path="@@.pagination@a.-1@href";
var data=java.getString(path);
var page=data.match(/_(\d+)/)[1];
var list=[{text:"第1页",href:baseUrl}];
if(data&&page){
